-- CHT-code 是 API key 對應繁體中文名稱的單一資料字典。
-- 舊資料同一 code_field 可能存在多筆不同 code_before，查詢排序後會拿到非預期內容；
-- 因此以目前保單服務 API／共用 UI 欄位重建一份唯一、可預期的標準對照。
DELETE FROM code_definition WHERE code_group = 'CHT-code';

INSERT INTO code_definition (
    code_definition_id, code_group, code_field, code_before, code_after, code_description,
    active_flag, review_status, created_by, created_at, reviewed_by, reviewed_at
)
